parameters.jsCode:
// SERP-Daten extrahieren
const response = $input.all()[0].json;
const tasks = response.tasks || [];
const results = tasks[0]?.result?.[0]?.items || [];

const organic = results
  .filter(item => item.type === 'organic')
  .slice(0, 10)
  .map((item, i) => ({
    position: i + 1,
    title: item.title || '',
    url: item.url || '',
    description: item.description || '',
    domain: item.domain || ''
  }));

// People Also Ask extrahieren
const paa = results
  .filter(item => item.type === 'people_also_ask')
  .flatMap(item => item.items || [])
  .map(item => item.title || item.question || '')
  .filter(Boolean);

return [{
  json: {
    top10_results: organic,
    top10_urls: organic.map(r => r.url),
    people_also_ask: paa,
    serp_summary: organic.map(r => `${r.position}. ${r.title} — ${r.description}`).join('\n')
  }
}];

// WDF*IDF Berechnung + Heading-Extraktion aus Top-10
const response = $input.all()[0].json;
const tasks = response.tasks || [];
const docs = [];
const allHeadings = []; // H2/H3 outlines from top 10

for (const task of tasks) {
  const result = task?.result?.[0];
  if (result?.items) {
    for (const item of result.items) {
      const text = (item.page_content?.body?.plain_text_word_count > 0)
        ? item.page_content.body.plain_text
        : '';
      if (text) docs.push(text.toLowerCase());

      // Extract headings (outlines from competitors)
      const h2s = item.page_content?.header?.h2 || [];
      const h3s = item.page_content?.header?.h3 || [];
      const url = item.url || task.data?.url || '';
      if (h2s.length > 0 || h3s.length > 0) {
        allHeadings.push({
          url: url,
          h2: h2s,
          h3: h3s
        });
      }
    }
  }
}

if (docs.length === 0) {
  return [{ json: { wdf_idf_terms: [], wdf_idf_summary: '', top10_outlines: allHeadings, top10_outlines_summary: 'Keine Outlines gefunden', error: 'Keine Inhalte gefunden' } }];
}

// Build outline summary for the outline generator
let outlineSummary = '';
for (let i = 0; i < allHeadings.length; i++) {
  const h = allHeadings[i];
  outlineSummary += `\n--- Seite ${i+1} (${h.url}) ---\n`;
  for (const heading of h.h2) {
    outlineSummary += `  H2: ${heading}\n`;
  }
  for (const heading of h.h3) {
    outlineSummary += `    H3: ${heading}\n`;
  }
}

// Stopwörter (deutsch)
const stopwords = new Set(['der','die','das','und','in','von','zu','für','mit','auf','den','des','dem','ein','eine','ist','im','an','es','als','auch','sich','nicht','aus','er','hat','sind','war','bei','wird','nach','oder','wie','einer','seine','kann','bis','über','so','zum','aber','nur','noch','da','ihr','wenn','was','vom','durch','zur','haben','mehr','um','diese','dieser','eines','keine','damit','schon','vor','einen','andere','andere','anderen','seinem','seinem','man','doch','wurde','werden','dass','wir','alle','kein','sehr','muss','zwischen','sein','unter','neue','seit','ihre','diese','selbst']);

// Terme zählen pro Dokument
const docTermCounts = docs.map(doc => {
  const words = doc.match(/[a-zäöüß]{3,}/g) || [];
  const counts = {};
  for (const w of words) {
    if (!stopwords.has(w)) counts[w] = (counts[w] || 0) + 1;
  }
  return { counts, total: words.length };
});

// IDF berechnen
const N = docs.length;
const allTerms = new Set();
for (const dtc of docTermCounts) {
  for (const t of Object.keys(dtc.counts)) allTerms.add(t);
}

const idf = {};
for (const term of allTerms) {
  const docsWithTerm = docTermCounts.filter(dtc => dtc.counts[term]).length;
  idf[term] = Math.log(N / docsWithTerm) + 1;
}

// WDF*IDF Score berechnen (Durchschnitt über alle Dokumente)
const wdfIdf = {};
for (const term of allTerms) {
  let totalScore = 0;
  for (const dtc of docTermCounts) {
    if (dtc.counts[term]) {
      const wdf = Math.log(dtc.counts[term] + 1) / Math.log(dtc.total);
      totalScore += wdf * idf[term];
    }
  }
  wdfIdf[term] = totalScore / N;
}

// Top-Terme sortieren
const sortedTerms = Object.entries(wdfIdf)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 50)
  .map(([term, score]) => ({ term, score: Math.round(score * 1000) / 1000 }));

const wdfSummary = sortedTerms.slice(0, 30).map(t => `${t.term} (${t.score})`).join(', ');

return [{
  json: {
    wdf_idf_terms: sortedTerms,
    wdf_idf_summary: wdfSummary,
    top10_outlines: allHeadings,
    top10_outlines_summary: outlineSummary || 'Keine Outlines extrahiert'
  }
}];

// Reddit-Ergebnisse und PAA extrahieren
const response = $input.all()[0].json;
const tasks = response.tasks || [];
const items = tasks[0]?.result?.[0]?.items || [];

const redditResults = items
  .filter(item => item.type === 'organic' && (item.url || '').includes('reddit.com'))
  .slice(0, 5)
  .map(item => ({
    title: item.title || '',
    url: item.url || '',
    description: item.description || ''
  }));

const paa = items
  .filter(item => item.type === 'people_also_ask')
  .flatMap(item => item.items || [])
  .map(item => item.title || item.question || '')
  .filter(Boolean);

// Merge mit bereits vorhandenen PAA
const existingPAA = $('Extract SERP Data').item.json.people_also_ask || [];
const allPAA = [...new Set([...existingPAA, ...paa])];

return [{
  json: {
    reddit_discussions: redditResults,
    reddit_summary: redditResults.map(r => `- ${r.title}: ${r.description}`).join('\n'),
    all_paa_questions: allPAA
  }
}];

// Interne Verlinkungsdaten aufbereiten
// Google Sheets API returns {values: [[headers], [row1], [row2], ...]}
const rawData = $input.first().json;
const values = rawData.values || [];

// Convert to keyed objects using header row
let sheetRows = [];
if (values.length > 1) {
  const headers = values[0];
  for (let i = 1; i < values.length; i++) {
    const row = {};
    for (let j = 0; j < headers.length; j++) {
      row[headers[j]] = values[i][j] || '';
    }
    sheetRows.push(row);
  }
}

const currentKeyword = $('Extract Task Data').item.json.keyword;
const themenCluster = $('Extract Task Data').item.json.themen_cluster || '';

// Filter by Themen-Cluster if available
let filteredRows = sheetRows;
if (themenCluster) {
  filteredRows = sheetRows.filter(row => 
    (row['Hub/Cluster'] || '').toLowerCase() === themenCluster.toLowerCase()
  );
}

const hubArticles = filteredRows
  .filter(row => (row['Keyword'] || '').toLowerCase() !== currentKeyword.toLowerCase())
  .map(row => ({
    keyword: row['Keyword'] || '',
    url: row['WordPress URL'] || row['Google Doc Link'] || '',
    status: row['Status'] || '',
    is_pillar: (row['Pillar Article URL'] || '').length > 0,
    pillar_url: row['Pillar Article URL'] || ''
  }));

const publishedArticles = hubArticles.filter(a => a.status === 'veröffentlicht' && a.url);
const pillarArticle = hubArticles.find(a => a.is_pillar);

return [{
  json: {
    hub_articles: hubArticles,
    published_articles: publishedArticles,
    pillar_article: pillarArticle || null,
    internal_linking_summary: publishedArticles.length > 0
      ? publishedArticles.map(a => `- "${a.keyword}": ${a.url}`).join('\n')
      : 'Noch keine veröffentlichten Artikel im Hub.'
  }
}];

// Claude-Antwort parsen und Outline extrahieren
const response = $input.all()[0].json;
const content = response.content?.[0]?.text || '';

// Extract JSON from code block
let jsonText = content.trim();
if (jsonText.startsWith('```')) {
  const lines = jsonText.split('\n');
  const start = 1;
  let end = lines.length;
  for (let i = lines.length - 1; i >= 0; i--) {
    if (lines[i].trim() === '```') { end = i; break; }
  }
  jsonText = lines.slice(start, end).join('\n');
}

// Fix trailing commas
jsonText = jsonText.replace(/,\s*([\]\}])/g, '$1');

let outline;
try {
  outline = JSON.parse(jsonText);
} catch (e) {
  // JSON might be truncated - try to repair
  let repaired = jsonText;

  // Count open/close brackets
  let openBraces = (repaired.match(/\{/g) || []).length;
  let closeBraces = (repaired.match(/\}/g) || []).length;
  let openBrackets = (repaired.match(/\[/g) || []).length;
  let closeBrackets = (repaired.match(/\]/g) || []).length;

  // Truncate at last complete section
  // Find the last complete "h2" section
  const lastCompleteSection = repaired.lastIndexOf('"infographic"');
  if (lastCompleteSection === -1) {
    // Find last complete h3_subsections array
    const lastH3 = repaired.lastIndexOf('"h3_subsections"');
  }

  // Simple repair: close all open brackets/braces
  // First, trim any incomplete key-value pairs
  repaired = repaired.replace(/,\s*"[^"]*"\s*:\s*[^,\]\}]*$/, '');
  repaired = repaired.replace(/,\s*\{[^\}]*$/, '');
  repaired = repaired.replace(/,\s*\[[^\]]*$/, '');

  // Add missing closers
  openBraces = (repaired.match(/\{/g) || []).length;
  closeBraces = (repaired.match(/\}/g) || []).length;
  openBrackets = (repaired.match(/\[/g) || []).length;
  closeBrackets = (repaired.match(/\]/g) || []).length;

  for (let i = 0; i < openBrackets - closeBrackets; i++) repaired += ']';
  for (let i = 0; i < openBraces - closeBraces; i++) repaired += '}';

  // Fix trailing commas again after repair
  repaired = repaired.replace(/,\s*([\]\}])/g, '$1');

  try {
    outline = JSON.parse(repaired);
  } catch (e2) {
    throw new Error('Konnte Outline-JSON nicht parsen (auch nach Reparatur): ' + e2.message + ' | First 300 chars: ' + jsonText.substring(0, 300));
  }
}

return [{
  json: {
    outline: outline,
    outline_json: JSON.stringify(outline, null, 2),
    title_suggestion: outline.title_suggestion || '',
    search_intent: outline.search_intent || '',
    section_count: (outline.sections || []).length,
    faq_count: (outline.faq_section || []).length,
    has_infographics: (outline.sections || []).some(s => s.infographic)
  }
}];

// Doc-Link aus ClickUp Custom Field 'Link zum Beitrag' extrahieren
const task = $('Fetch Task Details (ClickUp)').item.json;
const customFields = task.custom_fields || [];
const linkField = customFields.find(f => f.id === $('Config').item.json.clickup_custom_field_link);
const docUrl = linkField?.value || '';

// Doc ID aus URL extrahieren: https://docs.google.com/document/d/DOC_ID/edit
let docId = '';
if (docUrl) {
  const match = docUrl.match(/\/d\/([a-zA-Z0-9_-]+)/);
  docId = match ? match[1] : '';
}

return [{
  json: {
    doc_id: docId,
    doc_url: docUrl,
    has_doc: !!docId
  }
}];

// Normalize new doc info to match existing doc format
const docId = $('Create Google Doc (New)').item.json.id;
return [{
  json: {
    doc_id: docId,
    doc_url: `https://docs.google.com/document/d/${docId}/edit`,
    has_doc: true
  }
}];

// Prevent duplicate executions for the same task
const taskId = $('ClickUp Webhook Trigger').item.json.body?.task_id || '';
const now = Date.now();

// Get static data to track recent tasks
const staticData = $getWorkflowStaticData('global');
const recentTasks = staticData.recentTasks || {};

// Clean up entries older than 30 seconds
for (const [key, timestamp] of Object.entries(recentTasks)) {
  if (now - timestamp > 30000) {
    delete recentTasks[key];
  }
}

// Check if this task was already processed recently
if (recentTasks[taskId]) {
  // Duplicate! Stop execution
  return [];
}

// Mark as processing
recentTasks[taskId] = now;
staticData.recentTasks = recentTasks;

return $input.all();

// Build Perplexity request body - DEEP RESEARCH
const DEEP_RESEARCH_PROMPT = "# Deep Research Prompt: PKV Blog-Artikel  ---  ## Grundprinzip  KI ist nur ein Layer, nie die Quelle. Jede Antwort ist eine Hypothese, die gegen Originalquellen getestet wird. Nie auf eine einzige Quelle oder ein einzelnes KI-Antwortfenster verlassen. Immer bewusst mit Cross-Checks arbeiten.  ---  ## Minimaler Workflow (Schritt f\u00fcr Schritt)  ### Schritt 1: Scouting  Die erste Recherche-Runde dient ausschlie\u00dflich der Orientierung.  - Frage stellen: \u201eWelche offiziellen Reports, Studien und Prim\u00e4rquellen sind zentral zu Thema X?\" - Noch keine Inhalte \u00fcbernehmen - Nur relevante Quellen identifizieren und notieren  ### Schritt 2: Prim\u00e4rquellen lesen  - 5\u201310 Prim\u00e4rquellen \u00f6ffnen - Mindestens lesen: Abstract, Methodik, Datum, Fazit im Original - In einem separaten Dokument notieren: Quelle, Jahr, Stichprobe, Kernergebnis - Nichts \u00fcbernehmen, was nicht im Original gelesen wurde  ### Schritt 3: Systematischer Cross-Check  - F\u00fcr jede wichtige Aussage: Best\u00e4tigen mindestens 2\u20133 unabh\u00e4ngige, hochwertige Quellen genau dieselbe Aussage? - Weichen Zahlen oder Definitionen voneinander ab: neue Frage stellen, z. B. \u201eWarum unterscheiden sich Quelle A und Quelle B bei Kennzahl X?\" - Widerspr\u00fcche explizit herausarbeiten, nie gl\u00e4tten oder ignorieren - Keine Aussage \u00fcbernehmen, die nur eine einzige Quelle st\u00fctzt  ### Schritt 4: Zusammenfassung eingrenzen  Zweite Recherche-Runde mit folgendem Prompt:  > \u201eFasse nur diese gelisteten Quellen zusammen, nenne Widerspr\u00fcche und offene Fragen, keine weiteren Quellen hinzuziehen.\"  - Die finale Interpretation immer selbst schreiben, auf Basis der Originaltexte - KI nur zum Strukturieren, Vergleichen und Formulieren von Varianten nutzen  ---  ## Qualit\u00e4tsstandards f\u00fcr Quellen  ### Was als Quelle z\u00e4hlt  Jede verwendete Quelle muss eine Prim\u00e4rquelle sein:  - Originalstudie - Offizieller Report - Gesetzestext - Prim\u00e4rstatistik einer staatlichen oder anerkannten Institution  ### Was verboten ist  - Blogs - Tool-Anbieter - SEO-Artikel - Agentur-Websites - Sekund\u00e4rquellen ohne nachweisbare Originaldaten  ### Wenn Perplexity zu viele Sekund\u00e4rquellen liefert  Prompt anpassen:  > \u201eNur Peer-Reviewed Studien und offizielle Statistiken zitieren, keine Blogs oder Agentur-Websites.\"  ### Mindestanforderung zur \u00dcbernahme  Jede Aussage muss mit mindestens einer, idealerweise zwei unabh\u00e4ngigen Prim\u00e4rquellen verifizierbar sein. Ist das nicht m\u00f6glich, wird die Aussage weggelassen, ohne Ausnahme.  ---  ## Prompting gegen Halluzinationen  Folgende Anweisungen beim Recherchieren immer explizit verwenden:  - \u201eWenn keine verl\u00e4ssliche Prim\u00e4rquelle vorhanden ist, sag ausdr\u00fccklich, dass die Datenlage unsicher ist.\" - \u201eNenne mir, wo die Studienlage widerspr\u00fcchlich oder d\u00fcnn ist, statt eine eindeutige Antwort zu erfinden.\"  ---  ## Typische Fehlerquellen und wie du sie abf\u00e4ngst  | Fehlerquelle | Problem | L\u00f6sung | |---|---|---| | Veraltete Infos | Daten nicht mehr aktuell | Immer Ver\u00f6ffentlichungsjahr pr\u00fcfen, explizit nach Quellen ab 2022 fragen, \u00e4ltere Studien bewusst einordnen | | Kontextverlust | KI paraphrasiert Abstracts \u00fcberoptimistisch | Methodik und Limitations im Original lesen, bevor Zahlen \u00fcbernommen werden | | Konstruierte Zitate | Zeitschrift, DOI oder Institution existiert nicht | Studientitel separat \u00fcber Google Scholar oder direkt im Journal verifizieren | | Falsche Verallgemeinerung | Studie passt nicht auf den Kontext | Immer auf Population, Land und Zeitraum achten. Eine US-Studie aus 2017 ist kein globaler Stand 2026 |  ---  ## Quellenausgabe im fertigen Artikel  Jede Zahl, jede Statistik und jede Datenangabe bekommt direkt danach die vollst\u00e4ndig ausgeschriebene URL der Quelle. Keine Kurz-URLs, keine Verlinkungen ohne vollst\u00e4ndige Adresse.  **Format:**  > Aussage mit Datenpunkt. (https://www.beispielquelle.de/vollstaendiger-pfad-zur-seite)  **Beispiel:**  > Der durchschnittliche PKV-Beitrag lag 2024 bei X \u20ac. (https://www.pkv.de/verband/publikationen/zahlenbericht/)  ---  ## Bevorzugte Quellen (Priorit\u00e4t 1)  Diese Quellen werden bei der Recherche bevorzugt. Wo keine ausreichenden Daten gefunden werden, d\u00fcrfen andere seri\u00f6se Prim\u00e4rquellen genutzt werden, sofern sie den Qualit\u00e4tsstandards entsprechen.  ### Top-Quelle (immer zuerst)  Die Finanzpr\u00fcfer ist die prim\u00e4re Hauptquelle f\u00fcr jede Recherche. Sie wird als erstes konsultiert, bevor alle anderen Quellen herangezogen werden. Inhalte, Daten und Einsch\u00e4tzungen von dort haben Vorrang, solange sie den Qualit\u00e4tsstandards entsprechen und durch mindestens eine weitere Prim\u00e4rquelle verifizierbar sind.  | # | Quelle | Typ | URL | |---|--------|-----|-----| | 0 | Die Finanzpr\u00fcfer | Top-Quelle, immer zuerst | https://die-finanzpruefer.de/ |  ### Offizielle Stellen und Verb\u00e4nde  | # | Quelle | Typ | URL | |---|--------|-----|-----| | 1 | Verband der Privaten Krankenversicherung (PKV-Verband) | Branchenverband, Prim\u00e4r | https://www.pkv.de | | 2 | PKV-Wissensportal des Verbands | Infoportal | https://www.pkv.de/wissen/private-krankenversicherung/ | | 3 | privat-patienten.de (PKV-Verband) | Serviceportal | https://www.privat-patienten.de | | 4 | Bundesgesundheitsministerium (BMG) | Ministerium, Prim\u00e4r | https://www.bundesgesundheitsministerium.de/private-krankenversicherung | | 5 | Statistisches Bundesamt (Destatis) | Prim\u00e4rstatistik | https://www.destatis.de | | 6 | GDV | Branchenstatistik | https://www.gdv.de |  ### Verbraucherschutz und unabh\u00e4ngige Portale  | # | Quelle | Typ | URL | |---|--------|-----|-----| | 7 | Bund der Versicherten (BdV) | Verbraucherschutz | https://www.bundderversicherten.de | | 8 | Stiftung Warentest / Finanztest | Verbraucherorganisation | https://www.test.de | | 9 | Finanztip PKV \u00dcbersicht | Verbraucherportal | https://www.finanztip.de/pkv/ | | 10 | Finanztip PKV Kosten | Verbraucherportal | https://www.finanztip.de/pkv/pkv-kosten/ | | 11 | Finanztip PKV Standardtarif | Verbraucherportal | https://www.finanztip.de/pkv/pkv-standardtarif/ |  ### Spezialisierte Berater und Makler  | # | Quelle | Typ | URL | |---|--------|-----|-----| | 12 | Kanzlei ALBERS | Versicherungsberater | https://kanzlei-albers.de | | 13 | Dr. Schlemann Finanzberatung | Spezialisierter Berater | https://schlemann.com | | 14 | Finanzberatung Bierl | Spezialisierter Makler | https://www.finanzberatung-bierl.de | | 15 | KVoptimal.de | Spezialisierter Makler | https://kvoptimal.de |  ### PKV-Versicherer  | # | Quelle | Typ | URL | |---|--------|-----|-----| | 16 | Debeka Krankenversicherung | PKV-Versicherer | https://www.debeka.de | | 17 | Allianz Private Krankenversicherung | PKV-Versicherer | https://www.allianz.de/gesundheit/private-krankenversicherung/ | | 18 | AXA Krankenversicherung | PKV-Versicherer | https://www.axa.de |  ---  ## PKV-Tarifdaten f\u00fcr Beispiele und Vergleiche  Wenn der Artikel Tarifdaten oder Beitragsbeispiele ben\u00f6tigt, gelten folgende Regeln ohne Ausnahme.  ### Tarifh\u00f6he  - Ausschlie\u00dflich Hochleistungstarife ab 800 \u20ac monatlich verwenden - Tarife darunter werden nicht genannt, nicht verglichen und nicht als Beispiel herangezogen  ### Datenqualit\u00e4t  - Keine fiktiven Beispielzahlen - Ausschlie\u00dflich echte Tarife von echten Anbietern - Tarifdaten auf Basis der aktuellsten verf\u00fcgbaren Daten des jeweiligen Anbieters recherchieren  ### Bevorzugte Anbieter f\u00fcr Tarifdaten  Bei Bedarf an Tarifbeispielen oder Vergleichen immer zuerst recherchieren:  1. **Allianz** Private Krankenversicherung 2. **SDK** (S\u00fcddeutsche Krankenversicherung)  ### Verifizierung  - Jeden genannten Tarifbeitrag mit der vollst\u00e4ndigen Quell-URL des Anbieters belegen - Quelle muss aktuell und direkt abrufbar sein - Kein Tarifbeitrag ohne nachweisbare Prim\u00e4rquelle beim Anbieter selbst\n";

const keyword = $('Extract Task Data').item.json.keyword || '';
const serpSummary = $('Extract SERP Data').item.json.serp_summary || '';
const wdfSummary = $('WDF*IDF Calculator').item.json.wdf_idf_summary || '';

let paaQuestions = [];
try { paaQuestions = $('Extract Reddit & PAA').item.json.all_paa_questions || []; } catch(e) {}
const paaText = Array.isArray(paaQuestions) ? paaQuestions.join('\n') : String(paaQuestions);

let redditSummary = '';
try { redditSummary = $('Extract Reddit & PAA').item.json.reddit_summary || ''; } catch(e) {}

const userContent = `Recherchiere EXTREM umfassend und tiefgehend zum Thema: ${keyword}

## KONTEXT: TOP-10 GOOGLE-ERGEBNISSE
Die aktuellen Top-10 behandeln folgende Aspekte:
${serpSummary}

## WICHTIGE WDF*IDF TERME
Diese Begriffe sind laut Analyse besonders relevant:
${wdfSummary}

## HÄUFIG GESTELLTE FRAGEN (People Also Ask)
${paaText}

## REDDIT-DISKUSSIONEN (echte Nutzer-Perspektive)
${redditSummary}

## DEINE AUFGABE
Liefere eine VOLLSTÄNDIGE, TIEFGEHENDE Recherche die folgendes abdeckt:

1. **Fakten & Statistiken**: Alle relevanten Zahlen mit Primärquellen (Jahr, Institution, URL). Keine Zahl ohne Quelle.
2. **Aktuelle Gesetzeslage**: Relevante Paragraphen, Verordnungen, aktuelle Änderungen. Mit vollständiger URL zum Gesetzestext.
3. **Praxisbeispiele**: Konkrete Fälle, Szenarien, Rechenbeispiele die ein Berater seinen Kunden zeigen würde.
4. **Häufige Fehler & Missverständnisse**: Was wird oft falsch verstanden? Was raten Experten?
5. **Vergleiche & Übersichten**: Kosten, Optionen, Vor-/Nachteile. So detailliert wie möglich.
6. **Aktuelle Entwicklungen**: Was hat sich 2024/2025/2026 geändert? Neue Gesetze, Urteile, Trends?
7. **Expertenmeinungen**: Was sagen Verbraucherschützer, Verbände, unabhängige Berater?
8. **Widersprüche**: Wo gibt es unterschiedliche Meinungen? Wo ist die Datenlage dünn?

WICHTIG: 
- Jede Aussage mit vollständiger Quell-URL belegen
- Keine Blogs, keine SEO-Artikel, keine Agentur-Websites als Quelle
- Nur Primärquellen: Offizielle Statistiken, Gesetzestexte, Studien, Verbände
- Lieber "Datenlage unsicher" sagen als etwas erfinden
- Mindestens 3000 Wörter Recherche-Output`;

const body = {
  model: "sonar-deep-research",
  messages: [
    {
      role: "system",
      content: DEEP_RESEARCH_PROMPT
    },
    {
      role: "user",
      content: userContent
    }
  ],
  max_tokens: 8000,
  temperature: 0.1
};
