    docUrl = existing.doc_url || '';
  } catch(e) {}
}

const outlineJson = $('Parse Outline Response').item.json.outline_json || '{}';
const wdfSummary = $('WDF*IDF Calculator').item.json.wdf_idf_summary || '';
const wdfTerms = $('WDF*IDF Calculator').item.json.wdf_idf_terms || [];
const serpSummary = $('Extract SERP Data').item.json.serp_summary || '';

let perplexityContent = '';
try { perplexityContent = $('Perplexity Deep Research').item.json.choices?.[0]?.message?.content || ''; } catch(e) {}

const internalLinkingSummary = $('Prepare Internal Linking Data').item.json.internal_linking_summary || '';

let paaQuestions = [];
try { paaQuestions = $('Extract Reddit & PAA').item.json.all_paa_questions || []; } catch(e) {}

const body = {
  keyword,
  task_id: taskId,
  kunde,
  doc_id: docId,
  doc_url: docUrl,
  outline_json: outlineJson,
  wdf_idf_summary: wdfSummary,
  wdf_idf_terms: wdfTerms,
  perplexity_research: perplexityContent,
  internal_linking_summary: internalLinkingSummary,
  serp_summary: serpSummary,
  people_also_ask: paaQuestions
};

return [{ json: { trigger_body: body } }];
